/* THE HOLOGRAM SKIN — layout and material system from the mockups, as a theme
 * not a rebuild. Cool black ground, graphite panels, electric cyan for action,
 * blue for data, gold for genuine high value. Left behind: the fabricated
 * numbers and the render engine. Same real data, same gate. ?skin=warm reverts. */
const HOLO_SKIN = (() => {
  try {
    if (typeof window !== "undefined") {
      const q = new URLSearchParams(window.location.search).get("skin");
      if (q === "holo") return true;
      if (q === "warm") return false;
      const saved = window.localStorage && window.localStorage.getItem("hotl:skin");
      if (saved) return saved === "holo";
    }
  } catch (e) {}
  return true;
})();
