/* ---------------------------------- themes ----------------------------------- */
/**
 * Two things happen on the face of a card.
 *
 * 1. SCENE — a layered landscape of the county: sky wash, hazy far ridge, mid ridge,
 *    foreground, then the feature that actually identifies the place. Atmospheric
 *    perspective does the realism; each layer is lighter and lower-contrast than the
 *    one in front of it.
 *
 * 2. FOIL — the shiny-card treatment, and it is EARNED, not decorative. Tier comes
 *    from RARE plus the pattern checks below, so a holo card means the data on file
 *    lines up, and an unscored county is flat matte stock. Anything else would be
 *    selling excitement instead of evidence.
 */
function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  const f = (v) => Math.max(0, Math.min(255, Math.round(v + (amt > 0 ? (255 - v) * amt : v * amt))));
  return `#${[(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => f(v).toString(16).padStart(2, "0")).join("")}`;
}
function hexA(hex, a) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

function mix(a, b, t) {
  const A = parseInt(a.slice(1), 16), B = parseInt(b.slice(1), 16);
  const c = (sh) => Math.round((((A >> sh) & 255) * (1 - t)) + (((B >> sh) & 255) * t));
  return `#${[c(16), c(8), c(0)].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
}

/** Full-strength scene palettes. The county colour tints them, it does not drain them. */
const SCENE_PAL = {
  homes: { sky1: "#79B9E4", sky2: "#CFE6F2", far: "#8FB182", mid: "#63924C", near: "#4A7C39", deep: "#2C4A24", sun: "#FFE7A3" },
  city:  { sky1: "#4F7CB8", sky2: "#F0C98A", far: "#6E7F9E", mid: "#3E4C68", near: "#2A3448", deep: "#161C2A", sun: "#FFD873" },
  farm:  { sky1: "#82C2E8", sky2: "#E7EFC9", far: "#A8BE72", mid: "#7FA845", near: "#5F8A33", deep: "#3A5720", sun: "#FFE9A0" },
  coast: { sky1: "#6FC0E6", sky2: "#FFD9A8", far: "#2E9CC4", mid: "#1E82B4", near: "#EAD6A4", deep: "#144E70", sun: "#FFCF6B" },
  lake:  { sky1: "#77BEE8", sky2: "#D9EDF4", far: "#5E8C7A", mid: "#2F86A8", near: "#E3D5A8", deep: "#1B5570", sun: "#FFE6A6" },
};

const pal = (t) => {
  const base = SCENE_PAL[t.motif] || SCENE_PAL.homes;
  const tint = (hex, amt) => mix(hex, t.wash, amt);
  return {
    sky1: tint(base.sky1, .14), sky2: tint(base.sky2, .10),
    far: tint(base.far, .22), mid: tint(base.mid, .18), near: tint(base.near, .14),
    deep: tint(base.deep, .12), sun: base.sun,
  };
};

