const THEME_FALLBACK = { paper: "#17191D", band: "#1E2226", ink: "#EEE7D7", motif: "homes", wash: "#6B6450", character: "Mixed" };
const TERRAIN_MOTIF = { farmland: ["farm", "Farmland", "#7C7340"], rural: ["homes", "Rural", "#6B6450"], mountain: ["homes", "Mountain", "#4A5D7C"], swamp: ["lake", "Wetland", "#33513E"], beachfront: ["coast", "Coastal", "#2F6B5C"], city: ["city", "Metro", "#3E4F6B"], lakefront: ["lake", "Lakefront", "#356169"] };
const themeOf = (c) => {
  if (c && THEME[c.id]) return THEME[c.id];
  const tm = c && c.terrain && TERRAIN_MOTIF[c.terrain];
  return tm ? { ...THEME_FALLBACK, motif: tm[0], character: tm[1] + " — county database", wash: tm[2], band: shade(tm[2], -.35) } : THEME_FALLBACK;
};

function sceneUrl(t) {
  const p = pal(t);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 200" preserveAspectRatio="xMidYMax slice">
    <defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${p.sky1}"/><stop offset="1" stop-color="${p.sky2}"/>
    </linearGradient></defs>${SCENE[t.motif](p)}</svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg.replace(/\s+/g, " "))}")`;
}

/* ------------------------------ county links --------------------------------- */
/**
 * Only URLs actually retrieved and checked go in here. Anything we have not opened
 * ourselves is stored as null and renders as UNKNOWN — never a guessed URL. A missing
 * link is also why the matching capture item stays unchecked.
 *   OFFICIAL   county government, statute, or the official auction provider
 *   SECONDARY  reliable third-party documentation
 *   UNVERIFIED needs confirmation
 */
const LEVEL_DOT = { OFFICIAL: ["🟢", C.green], SECONDARY: ["🟡", C.amber], DIRECT: ["🟡", C.amber], GENERIC: ["⚪", C.inkSoft], UNVERIFIED: ["🔴", C.red] };
const LEVEL_NOTE = { OFFICIAL: "opened and read", SECONDARY: "reliable third party", DIRECT: "direct link, machine-collected — not yet opened", GENERIC: "generic page", UNVERIFIED: "derived, may not resolve" };
const unpackUrl = (u) => !u ? "" : u.startsWith("w:") ? "https://www." + u.slice(2) : u.startsWith("h:") ? "https://" + u.slice(2) : u.startsWith("pw:") ? "http://www." + u.slice(3) : u.startsWith("p:") ? "http://" + u.slice(2) : u;
const LINK_KIND_KEY = { as: "assessor", gi: "gis", re: "recorder", co: "court", pl: "platform", ot: "otc", tr: "treasurer" };
const LINK_KIND_LABEL = { assessor: "Assessor", gis: "GIS parcel viewer", recorder: "Recorder", court: "Clerk / court records", platform: "Auction platform", otc: "County OTC page", treasurer: "Treasurer" };
/** Links from the county database for any county, as LinkList rows. */
function dbLinks(c) {
  const r = NAT_BY_NAME[`${c.name}|${c.state}`]; if (!r || !r[22]) return [];
  return Object.entries(r[22]).map(([k, [u, lv]]) => [LINK_KIND_KEY[k] || k, `${c.name} County — ${LINK_KIND_LABEL[LINK_KIND_KEY[k] || k]}`, unpackUrl(u), lv === "O" ? "OFFICIAL" : "DIRECT"]);
}

