/** Which capture item a missing link blocks — the link IS the evidence. */
const LINK_BLOCKS = { treasurer: "rule-auction", platform: "auc-platform", assessor: "src-assessor",
  gis: "src-gis", recorder: "src-recorder", court: "src-court", statute: "law-rate", otc: "out-otc" };

function linksFor(c) {
  // This build carries link kinds and levels but not the URLs — they were 225 KB and
  // the app has to load on a phone. Verified counties still carry real URLs through
  // COUNTY_VERIFIED; everything else reports what exists and where to get it.
  const row = NAT_BY_NAME[`${c.name}|${c.state}`];
  const kinds = row && row[22] ? row[22] : {};
  const verified = (COUNTY_VERIFIED.links || {})[c.id] || [];
  const MAP = { as: "assessor", gi: "gis", re: "recorder", co: "treasurer", pl: "platform", ot: "otc" };
  const out = [];
  for (const [k, v] of Object.entries(kinds)) {
    const kind = MAP[k] || k;
    const real = verified.find((x) => x[0] === kind);
    out.push({ kind, hits: real ? [real] : [], level: Array.isArray(v) ? v[1] : "DIRECT", urlHeld: !!real });
  }
  for (const v of verified) if (!out.some((o) => o.kind === v[0])) out.push({ kind: v[0], hits: [v], level: v[3] || "OFFICIAL", urlHeld: true });
  return out;
}

function LinkList({ c }) {
  const rows = linksFor(c);
  return (
    <div>
      {rows.map(({ kind, label, hits, note }) => (
        <div key={kind} style={{ borderBottom: `1px solid ${C.edge}`, padding: "9px 0" }}>
          <div style={{ fontFamily: F.stat, fontSize: 10, color: C.inkSoft, marginBottom: 3 }}>{label}</div>
          {note && <div style={{ fontFamily: F.body, fontSize: 12.5, color: C.ink, lineHeight: 1.45, marginBottom: 6 }}>{note}</div>}
          {hits.length === 0 ? (
            <div>
              <div style={{ fontFamily: F.stat, fontSize: 12.5, color: C.red }}>🔴 UNKNOWN — no link on file</div>
              <div style={{ fontFamily: F.body, fontSize: 12.5, color: C.inkSoft, marginTop: 2, lineHeight: 1.4 }}>
                Find it, open it, and store the URL. That is what checks the “{
                  (CAPTURE_ITEMS.find((i) => i.id === LINK_BLOCKS[kind]) || {}).text || "matching"
                }” item.
              </div>
            </div>
          ) : hits.map(([, text, url, level]) => (
            <Out key={url} href={url}
              style={{ display: "block", textDecoration: "none", marginBottom: 4 }}>
              <span style={{ fontFamily: F.body, fontSize: 13.5, color: C.ink, lineHeight: 1.4,
                borderBottom: `1px solid ${hexA(C.ink, .35)}` }}>{text}</span>
              <span style={{ display: "block", fontFamily: F.stat, fontSize: 10, marginTop: 2,
                color: LEVEL_DOT[level][1] }}>
                {LEVEL_DOT[level][0]} {level} · {LEVEL_NOTE[level]} · {(() => { const f = FRESHNESS(level === "DIRECT" ? SOURCE_DATES.database : level === "OFFICIAL" || level === "SECONDARY" ? SOURCE_DATES.countyPages : SOURCE_DATES.scrape); return `${f.label} ${f.age != null ? f.age + "d" : ""}`; })()} · authority L{AUTHORITY[level] || 6} · opens in a new tab
              </span>
            </Out>
          ))}
        </div>
      ))}
      <p style={{ fontFamily: F.stat, fontSize: 10.5, color: C.inkSoft, marginTop: 10, lineHeight: 1.5 }}>
        County pages move without notice. A stored link is evidence only as of the date it was
        checked — re-open it before you register or bid.
      </p>
    </div>
  );
}

/* ============================ CAPTURE SYSTEM ================================
 * A county is not captured by clicking anything. It is captured when the required
 * research is done. Shine is a claim about how well we know a jurisdiction — never
 * a claim that it is a good investment.
 * ========================================================================== */
const REQ = "required", REC = "recommended", OPT = "optional";
const XP_FOR = { [REQ]: 25, [REC]: 15, [OPT]: 10 };
const CAPTURE_XP = 500;

const CAPTURE_GROUPS = [
  { id: "law", name: "State law", items: [
    ["law-type", REQ, "Sale type verified (lien, deed, or redeemable deed)"],
    ["law-rate", REQ, "Statutory interest or penalty verified against the statute"],
    ["law-redeem", REQ, "Redemption period verified"],
    ["law-deed", REQ, "Foreclosure or deed process verified"],
  ]},
  { id: "rules", name: "County rules", items: [
    ["rule-auction", REQ, "Official auction rules obtained for the current year"],
    ["rule-register", REQ, "Registration requirements confirmed"],
    ["rule-deposit", REQ, "Deposit requirement confirmed"],
    ["rule-bid", REQ, "Bidding method confirmed (premium, bid-down, rotational, random)"],
    ["rule-pay", REQ, "Payment method and deadline confirmed"],
    ["rule-issue", REC, "Certificate or deed issuance process confirmed"],
  ]},
  { id: "data", name: "County data sources", items: [
    ["src-treasurer", REQ, "Treasurer or tax collector search tested"],
    ["src-assessor", REQ, "Assessor search tested"],
    ["src-gis", REQ, "GIS parcel viewer tested"],
    ["src-recorder", REQ, "Recorder index tested"],
    ["src-court", REC, "Clerk or court records tested"],
  ]},
  { id: "auction", name: "Auction intelligence", items: [
    ["auc-platform", REQ, "Auction platform identified"],
    ["auc-date", REQ, "Next auction date confirmed"],
    ["auc-deadline", REQ, "Registration and deposit deadlines confirmed"],
    ["auc-list", REQ, "Parcel list source located"],
    ["auc-terms", REC, "Current-year terms document stored"],
    ["auc-contacts", REC, "County contact details verified"],
    ["auc-inventory", OPT, "Parcel inventory imported"],
  ]},
  { id: "title", name: "Title and property workflow", items: [
    ["ttl-lookup", REC, "Property lookup workflow tested end to end"],
    ["ttl-recorder", REC, "Recorded document workflow tested"],
    ["ttl-lien", REC, "Lien and encumbrance search workflow tested"],
    ["ttl-hoa", REC, "HOA and special district research method established"],
    ["ttl-access", REC, "Legal access research method established"],
    ["ttl-hazard", REC, "Flood, wildfire and environmental method established"],
  ]},
  { id: "human", name: "Human verification", items: [
    ["hv-links", REQ, "Official source links stored with retrieval dates"],
    ["hv-conflict", REQ, "Conflicting information resolved or flagged"],
    ["hv-recent", REC, "Sources re-checked inside the review window"],
    ["hv-review", REC, "Critical rules reviewed by a person, not just extracted"],
    ["hv-watch", OPT, "Rule-change monitoring enabled"],
  ]},
  { id: "outcome", name: "Outcomes", items: [
    ["out-hist", OPT, "Historical auction results recorded"],
    ["out-otc", OPT, "Over-the-counter process verified"],
    ["out-redeem", OPT, "Redemption outcomes recorded"],
    ["out-perf", OPT, "Performance data feeding the learning engine"],
  ]},
];

const CAPTURE_ITEMS = CAPTURE_GROUPS.flatMap((g) =>
  g.items.map(([id, weight, text]) => ({ id, weight, text, group: g.id, groupName: g.name })));
const REQUIRED_IDS = CAPTURE_ITEMS.filter((i) => i.weight === REQ).map((i) => i.id);
const SOFT_IDS = CAPTURE_ITEMS.filter((i) => i.weight !== REQ).map((i) => i.id);

/**
 * Seeds: only what the app can already evidence. State-law items seed where
 * STATE_RULES carries a verified citation; county items only where a sourced record
 * actually contains that fact. Scored demo counties carry a deeper synthetic history.
 */
function seedFor(c) {
  const out = new Set();
  const R = rulesFor(c.state);
  if (R && R.verified) { out.add("law-type"); out.add("law-rate"); out.add("law-redeem"); }
  if (c.sources && c.sources.length) out.add("hv-links");
  if (c.facts) {
    const blob = c.facts.map((f) => f[0] + " " + f[1]).join(" ").toLowerCase();
    if (blob.includes("bid")) out.add("rule-bid");
    if (blob.includes("online") || blob.includes("realauction") || blob.includes("govease")
        || blob.includes("sri") || blob.includes("in person")) out.add("auc-platform");
    if (blob.includes("sale date") || blob.includes("held")) out.add("auc-date");
    if (blob.includes("deadline") || blob.includes("registration")) { out.add("auc-deadline"); out.add("rule-register"); }
    if (blob.includes("publication") || blob.includes("list")) out.add("auc-list");
    if (blob.includes("deed") || blob.includes("foreclos")) out.add("law-deed");
    if (!c.conflict) out.add("hv-conflict");
  }
  if (c.hist) out.add("out-hist");
  if (c.verifiedCounty) {
    const blob = (c.facts || []).map((f) => f[0] + " " + f[1]).join(" ").toLowerCase();
    out.add("auc-platform");
    if (/deposit/.test(blob)) out.add("rule-deposit");
    if (/registration|w-9/.test(blob)) out.add("rule-register");
    if (/pay|non-payment|civil action|direct-deposit/.test(blob)) out.add("rule-pay");
    if (/20\d\d sale|sale timing|cadence/.test(blob)) out.add("auc-date");
    if (/subsequent|sub-tax/.test(blob)) out.add("rule-issue");
    if (c.outcomeSources && c.outcomeSources.length) out.add("out-hist");
    if (COUNTY_VERIFIED.otc_county[`${c.state}|${c.name}`]) out.add("out-otc");
    if (OUTCOME_STATS[`${c.state}|${c.name}`]) { out.add("out-hist"); out.add("out-perf"); }
    if (c.links && c.links.length) { out.add("hv-links"); out.add("rule-auction"); }
    if (!c.conflict) out.add("hv-conflict");
  }
  if (c.scores) ["rule-auction", "rule-pay", "src-treasurer", "src-assessor", "src-gis",
    "src-recorder", "auc-terms", "auc-contacts", "ttl-lookup", "ttl-recorder"].forEach((i) => out.add(i));
  return [...out];
}

const _seedCache = new Map();
const seedCached = (c) => { if (!_seedCache.has(c.id)) _seedCache.set(c.id, seedFor(c)); return _seedCache.get(c.id); };
const _capCache = new WeakMap();   // checks object → Map(county id → result)
const _capNoChecks = new Map();
function captureOf(c, checks) {
  const store = checks ? (_capCache.get(checks) || (_capCache.set(checks, new Map()), _capCache.get(checks))) : _capNoChecks;
  if (store.has(c.id)) return store.get(c.id);
  const out = computeCapture(c, checks);
  store.set(c.id, out);
  return out;
}
function computeCapture(c, checks) {
  const user = (checks || {})[c.id] || {};
  const done = new Set([...seedCached(c), ...Object.keys(user).filter((k) => user[k])]);
  const reqDone = REQUIRED_IDS.filter((i) => done.has(i)).length;
  const softDone = SOFT_IDS.filter((i) => done.has(i)).length;
  const reqPct = Math.round((reqDone / REQUIRED_IDS.length) * 100);
  const softPct = Math.round((softDone / SOFT_IDS.length) * 100);
  const pct = Math.round(((reqDone + softDone) / CAPTURE_ITEMS.length) * 100);
  const captured = reqDone === REQUIRED_IDS.length;
  let tier;
  if (captured) {
    tier = softPct >= 100 ? "legendary" : softPct >= 85 ? "holographic"
      : softPct >= 65 ? "gold" : softPct >= 40 ? "silver" : "standard";
  } else {
    tier = pct >= 75 ? "near" : pct >= 50 ? "researching" : pct >= 25 ? "discovered" : "undiscovered";
  }
  const missing = CAPTURE_ITEMS.filter((i) => i.weight === REQ && !done.has(i.id));
  return { done, pct, reqPct, softPct, captured, tier, missing,
    reqDone, reqTotal: REQUIRED_IDS.length, softDone, softTotal: SOFT_IDS.length };
}

/** Visual treatment per state. Shine tracks knowledge, not opportunity. */
/** Materials. Brushed = fine repeating lines over the metal gradient. */
const BRUSH = "repeating-linear-gradient(115deg, rgba(255,255,255,.045) 0 1px, rgba(0,0,0,.05) 1px 3px)";
const METAL = {
  charcoal: `linear-gradient(145deg,#2A2D32,#16181B 45%,#25282D)`,
  graphite: `linear-gradient(145deg,#3A3E44,#1E2126 45%,#33373D)`,
  gunmetal: `linear-gradient(140deg,#4B5158,#2A2E34 40%,#464B52,#23272C)`,
  bronze:   `linear-gradient(140deg,#B48A55,#6E4E2A 40%,#C29A62,#5A3E20)`,
  brass:    `linear-gradient(140deg,#BBA46A,#6F5B33 40%,#CDB77E,#5D4B28)`,
  platinum: `linear-gradient(140deg,#F1F2F4,#B8BEC5 35%,#E4E7EA,#8E959C)`,
  gold:     `linear-gradient(140deg,#F4E2A6,#C9A44C 35%,#F6E7B4,#8C6B22)`,
  obsidian: `linear-gradient(140deg,#5B6B8C,#1D2230 40%,#4E5F7E,#12161F)`,
  prism:    `conic-gradient(from 210deg,#F4E2A6,#C9A44C,#E8B9D4,#9FD3E8,#B9E6C9,#F4E2A6)`,
};
const CARD_STATE = {
  undiscovered: { label: "Undiscovered", foil: 0, mark: "○", color: "#6B7076", dim: .5,  frame: METAL.charcoal, liner: "#0E0F11", glow: "none" },
  discovered:   { label: "Discovered",   foil: 0, mark: "○", color: "#8E9399", dim: .78, frame: METAL.graphite, liner: "#0E0F11", glow: "none" },
  researching:  { label: "Researching",  foil: .1, mark: "◇", color: "#A9B0B8", dim: .92, frame: METAL.gunmetal, liner: "#0E0F11", glow: "none" },
  near:         { label: "Near capture", foil: .26, mark: "◆", color: "#C9A44C", dim: 1, frame: METAL.bronze, liner: "#1A120A", glow: "0 0 26px rgba(180,138,85,.35)" },
  standard:     { label: "Captured",     foil: .3, mark: "★", color: "#CDB77E", dim: 1, frame: METAL.brass, liner: "#171308", glow: "0 0 24px rgba(187,164,106,.35)" },
  silver:       { label: "Platinum",     foil: .38, mark: "★", color: "#D9DCE0", dim: 1, frame: METAL.platinum, liner: "#2A2E33", glow: "0 0 30px rgba(220,225,230,.4)" },
  gold:         { label: "Gold foil",    foil: .46, mark: "★★", color: "#EFD892", dim: 1, frame: METAL.gold, liner: "#2B2007", glow: "0 0 34px rgba(201,164,76,.55)" },
  holographic:  { label: "Obsidian holo", foil: .6, mark: "★★★", color: "#9FD3E8", dim: 1, frame: METAL.obsidian, liner: "#0B0E15", glow: "0 0 36px rgba(120,160,220,.55)" },
  legendary:    { label: "Legendary",    foil: .74, mark: "✦✦✦", color: "#F4E2A6", dim: 1, frame: METAL.prism, liner: "#1A140A", glow: "0 0 46px rgba(244,226,166,.6)" },
};

const SHINE_RULE = {
  standard: "Every required item verified.",
  silver: "Required complete, plus auction intelligence and county contacts.",
  gold: "Silver, plus title workflows tested and sources cross-checked.",
  holographic: "Gold, plus real auction and redemption outcomes on file.",
  legendary: "Everything verified, monitored, human-reviewed and outcome-trained.",
};

const CaptureCtx = React.createContext({ checks: {}, toggle: () => {} });
const HoloCtx = React.createContext(false);
/** Star LEVELS, 1–5, like the level row on a monster card. Level ≥ 1 puts it on the watchlist.
 *  Separate from Keep/Pass (which move research) and from shine (which is earned by verification).
 *  Keys: "county:<id>" | "parcel:<id>". Value: 1–5. */
const StarCtx = React.createContext({ stars: {}, setLevel: () => {}, toggleStar: () => {} });
const levelOf = (stars, k) => { const v = stars[k]; return typeof v === "number" ? v : v ? 3 : 0; };

function StarGem({ on, size = 18, dim }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden style={{ display: "block", filter: on ? "drop-shadow(0 0 4px rgba(239,216,146,.65))" : "none", opacity: dim ? .55 : 1 }}>
      <defs>
        <radialGradient id="gemOn" cx="38%" cy="32%" r="70%"><stop offset="0" stopColor="#F6E7B4" /><stop offset=".55" stopColor="#C9A44C" /><stop offset="1" stopColor="#7A5A16" /></radialGradient>
        <radialGradient id="gemOff" cx="38%" cy="32%" r="70%"><stop offset="0" stopColor="#3A3F46" /><stop offset="1" stopColor="#15181C" /></radialGradient>
      </defs>
      <circle cx="12" cy="12" r="11" fill={on ? "url(#gemOn)" : "url(#gemOff)"} stroke={on ? "#8C6B22" : "#2B2F35"} strokeWidth="1" />
      <path d="M12 4.6l2.2 4.6 5 .7-3.6 3.5.9 5-4.5-2.4-4.5 2.4.9-5L4.8 9.9l5-.7z" fill={on ? "#FFF6D8" : "#0F1114"} stroke={on ? "#8C6B22" : "#3B4047"} strokeWidth=".6" />
      <ellipse cx="9.5" cy="8" rx="3" ry="1.6" fill="rgba(255,255,255,.35)" transform="rotate(-25 9.5 8)" />
    </svg>
  );
}
/** Tap a socket to set that level; tap the current level again to clear. */
function StarRow({ k, size = 18, label = true, style }) {
  const { stars, setLevel } = useContext(StarCtx);
  const lv = levelOf(stars, k);
  const [pop, setPop] = useState(0);
  return (
    <div data-nodrag role="radiogroup" aria-label="Star level" style={{ display: "flex", alignItems: "center", gap: 4, ...style }}>
      {label && <span style={{ fontFamily: F.label, fontSize: 8.5, letterSpacing: 2, color: C.inkSoft, marginRight: 4 }}>LEVEL</span>}
      {[1, 2, 3, 4, 5].map((i) => (
        <button key={i} role="radio" aria-checked={lv === i} aria-label={`Level ${i}`} title={`Level ${i}${lv === i ? " — tap to clear" : ""}`}
          onClick={(e) => { e.stopPropagation(); e.preventDefault(); const next = lv === i ? 0 : i; setLevel(k, next); if (next > lv) { setPop(i); setTimeout(() => setPop(0), 520); } }}
          className={pop >= i && pop > 0 ? "starPop" : ""}
          style={{ background: "transparent", border: "none", padding: 0, cursor: "pointer", lineHeight: 0 }}>
          <StarGem on={i <= lv} size={size} />
        </button>
      ))}
    </div>
  );
}
/** Read-only compact row for lists and tiles. */
const StarMini = ({ level, size = 12 }) => (
  <span style={{ display: "inline-flex", gap: 2, verticalAlign: "middle" }}>{[1, 2, 3, 4, 5].map((i) => <StarGem key={i} on={i <= level} size={size} dim={i > level} />)}</span>
);
function StarButton({ k, size = 20, style }) {
  const { stars, toggleStar } = useContext(StarCtx);
  const on = levelOf(stars, k) > 0;
  const [pop, setPop] = useState(false);
  return (
    <button data-nodrag aria-pressed={on} aria-label={on ? "Unstar" : "Star"} title={on ? "Starred — on your watchlist" : "Star this"}
      onClick={(e) => { e.stopPropagation(); e.preventDefault(); toggleStar(k); if (!on) { setPop(true); setTimeout(() => setPop(false), 520); } }}
      className={pop ? "starPop" : ""}
      style={{ background: "transparent", border: "none", cursor: "pointer", padding: 2, lineHeight: 1, fontSize: size,
        color: on ? "#EFD892" : "rgba(238,231,215,.45)", textShadow: on ? "0 0 8px rgba(239,216,146,.65), 0 1px 0 rgba(0,0,0,.6)" : "0 1px 0 rgba(0,0,0,.6)", ...style }}>
      {on ? "★" : "☆"}
    </button>
  );
}

/* ============================ CARD FAMILIES ==================================
 * Lien cards read as financial certificates: graphite, emerald, antique gold,
 * banknote guilloche. Deed cards read as property instruments: obsidian, navy,
 * platinum, copper, cadastral topography. The instrument decides the family;
 * research depth decides how much of the family's foil is earned.
 * ========================================================================== */
const FAMILY = {
  certificate: {
    key: "certificate", label: "TAX LIEN CERTIFICATE", short: "LIEN",
    base: "#0B0D0F", stock: "#15181C", liner: "#0A0C0E",
    foil: "#D6B65E", foilLt: "#F0DD9A", foilDk: "#8C6B22", accent: "#3F8F5E", accentLt: "#75C695",
    foilText: { backgroundImage: "linear-gradient(170deg,#F0DD9A 0%,#D6B65E 40%,#8C6B22 62%,#F0DD9A 100%)",
      WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", filter: "drop-shadow(0 1px 0 rgba(0,0,0,.55))" },
    hairline: "linear-gradient(90deg, rgba(214,182,94,0), rgba(214,182,94,.9) 20%, rgba(240,221,154,.95) 50%, rgba(214,182,94,.9) 80%, rgba(214,182,94,0))",
    holo: "certificate", spectrum: ["#D6B65E", "#3F8F5E", "#4ED0E0", "#6E5FA8"],
    says: "Income-producing certificate backed by a real parcel",
  },
  deed: {
    key: "deed", label: "TAX DEED", short: "DEED",
    base: "#0A0C12", stock: "#161922", liner: "#080A10",
    foil: "#D9DCE0", foilLt: "#F2F4F6", foilDk: "#9CA4AE", accent: "#B97846", accentLt: "#D49A66",
    foilText: { backgroundImage: "linear-gradient(170deg,#F2F4F6 0%,#D9DCE0 40%,#9CA4AE 62%,#F2F4F6 100%)",
      WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", filter: "drop-shadow(0 1px 0 rgba(0,0,0,.6))" },
    hairline: "linear-gradient(90deg, rgba(217,220,224,0), rgba(185,120,70,.9) 20%, rgba(242,244,246,.95) 50%, rgba(185,120,70,.9) 80%, rgba(217,220,224,0))",
    holo: "topographic", spectrum: ["#D9DCE0", "#4ED0E0", "#4A426A", "#B97846"],
    says: "May lead toward ownership of the underlying property — never guaranteed",
  },
};
const getInstrumentTheme = (c) => (/deed/i.test(c?.instrument || "") ? FAMILY.deed : FAMILY.certificate);
const getResearchTier = (c, checks) => captureOf(c, checks).tier;
const getHoloPattern = (c, tier) => {
  if (tier === "legendary") return "prism";
  if (tier === "holographic") return "obsidian";
  if (tier === "silver") return "platinum";
  return getInstrumentTheme(c).holo;
};
/** Data confidence changes the finish, never the tier. */
const getConfidenceTreatment = (c) => {
  const conf = c?.scores?.confidence ?? (c?.verifiedCounty ? Math.min(90, 55 + (c.facts?.length || 0) * 5) : c?.sourced ? 60 : 35);
  return conf < 50 ? { filter: "saturate(.78) brightness(.94)", label: "Low confidence", conf }
    : conf < 75 ? { filter: "saturate(.9)", label: "Partial confidence", conf }
    : conf < 90 ? { filter: "none", label: "Strong finish", conf }
    : { filter: "saturate(1.04) contrast(1.02)", label: "High confidence", conf };
};

