const PATTERNS = {
  heating:   { label: "Heating up",        icon: "▲", w: 3, why: "Bidders rising while winning rates fall in the county's own published results." },
  floor:     { label: "Floor crowded",     icon: "▬", w: 3, why: "Most certificates sold at the rate floor — the headline rate is not what wins." },
  thin:      { label: "Thin list",         icon: "◇", w: 2, why: "Half or more of the published list went unsold at the sale." },
  income:    { label: "Income play",       icon: "%", w: 2, why: "Deeds are rare here by the county's numbers; this county pays interest, it does not hand over dirt." },
  acquire:   { label: "Acquisition play",  icon: "⌂", w: 2, why: "Deed instrument — the parcel itself is what changes hands." },
  fixed:     { label: "Fixed-rate shield", icon: "≡", w: 3, why: "Rate is set by statute and not bid down; competition shows up as a draw or a percentage, not a lower yield." },
  premium:   { label: "Premium trap",      icon: "▽", w: 2, why: "Premium bid state — anything paid over face is gone and earns nothing." },
  otc:       { label: "OTC open",          icon: "◎", w: 2, why: "County-held or state-assigned inventory purchasable off-auction, with a link on file." },
  window:    { label: "Sale window",       icon: "◷", w: 3, why: "A verified sale date lands inside the next 90 days." },
  rolling:   { label: "Rolling sales",     icon: "↻", w: 2, why: "County runs adjourned or monthly sales after the annual auction." },
  fast:      { label: "Fast reload",       icon: "⟳", w: 2, why: "Statutory redemption of two years or less, or a penalty earned regardless of hold." },
  edge:      { label: "Data edge",         icon: "◆", w: 3, why: "Six or more official county facts plus parsed outcome data — more than a list broker will show." },
  conflict:  { label: "Conflict to resolve", icon: "⚠", w: -2, why: "Sources disagree on a fact that changes the instrument or the return — lien vs deed, or the rate itself." },
  stale:     { label: "Stale record",      icon: "◌", w: -2, why: "The most recent sale on file has already happened, or the record is out of cycle." },
  unknown:   { label: "Unverified state",  icon: "?", w: -3, why: "State rules not verified against the statute — every figure is a lead." },
  home:      { label: "Home turf",         icon: "⌖", w: 1, why: "Inside the operating base (CO, ID, WA) — cheap to inspect and to attend in person." },
  regime:    { label: "New regime",        icon: "§", w: 2, why: "The statute changed recently or is changing — rules the crowd learned no longer apply, and procedures are untested." },
};
const REGIME_CHANGE = { LA: "lien certificates from Jan 1, 2026", IL: "2025 sale paused; 2026 reform passed", CO: "deed process changed July 2024; 2026 changes" };
const _patCache = new Map();
function detectPatterns(c) {
  const key = c.id;
  if (_patCache.has(key)) return _patCache.get(key);
  const hits = [];
  const R = rulesFor(c.state);
  const fam = getInstrumentTheme(c);
  const stats = OUTCOME_STATS[`${c.state}|${c.name}`];
  const otc = COUNTY_VERIFIED.otc_county[`${c.state}|${c.name}`] || (COUNTY_LINKS[c.id] || []).find((l) => l[0] === "otc");
  const facts = (c.facts || []).length;
  const blob = (c.facts || []).map((f) => f[0] + " " + f[1]).join(" ").toLowerCase() + " " + Object.values(c.stats || {}).join(" ").toLowerCase();
  const add = (id, ev) => hits.push({ id, ...PATTERNS[id], evidence: ev });

  if (stats) {
    if (stats.bidders_yoy > 0 && stats.rate_yoy != null && stats.rate_yoy < 0) add("heating", `bidders ${stats.bidders_yoy > 0 ? "+" : ""}${stats.bidders_yoy}, rate ${stats.rate_yoy} pts`);
    if (stats.floor_share_pct >= 40) add("floor", `${stats.floor_share_pct}% of certificates at the floor`);
    if (stats.sale_through_pct != null && stats.sale_through_pct <= 60) add("thin", `${stats.sale_through_pct}% sale-through`);
    if (stats.deed_to_sold_pct != null && stats.deed_to_sold_pct < 3) add("income", `${stats.deed_to_sold_pct}% deeds ÷ liens sold`);
  }
  if (!stats && /deed[^.]{0,80}(under|less than) 1%/.test(blob)) add("income", "county states deed transfer under 1% of purchases");
  if (c.hist && c.hist.redeemedPct >= 80 && !hits.some((h) => h.id === "income")) add("income", `${c.hist.redeemedPct}% redeemed*`);
  if (fam.key === "deed") add("acquire", c.instrument);
  if (R.verified && (R.mechanism === "penalty" || R.mechanism === "monthly")) add("fixed", R.headline);
  if (R.verified && R.mechanism === "premium") add("premium", R.headline);
  if (otc) add("otc", "OTC link on file");
  else { const d = otcFor(c); if (d && d.status === "CONFIRMED") add("otc", `OTC directory CONFIRMED · ${d.phone ? "call " + d.phone : "call the office"}`); }
  const ns = NEXT_SALE[`${c.state}|${c.name}`];
  if (ns) {
    const days = Math.round((new Date(ns) - TODAY) / 86400000);
    if (days >= 0 && days <= 90) add("window", `${days} days — ${ns}`);
    if (days < 0) add("stale", `sale on file ${ns} has passed`);
  }
  if (/adjourned|monthly|year-round|first come/.test(blob)) add("rolling", "adjourned / year-round sales per county");
  if (R.verified && ((R.mechanism === "penalty") || (R.redemption && /\b(1|2) year|21 mo|24 mo/.test(String(R.redemption))) || c.state === "FL" || c.state === "IA")) add("fast", R.redemption || R.headline);
  if (facts >= 6 && stats) add("edge", `${facts} official facts + parsed outcomes`);
  if (c.conflict) add("conflict", c.conflict.slice(0, 80) + "…");
  if (c.stale && !hits.some((h) => h.id === "stale")) add("stale", c.stale.slice(0, 80) + "…");
  if (!R.verified) add("unknown", `${c.state} rulebook not verified`);
  if (["CO", "ID", "WA"].includes(c.state)) add("home", c.state);
  if (REGIME_CHANGE[c.state]) add("regime", REGIME_CHANGE[c.state]);

  const score = hits.reduce((a, h) => a + h.w, 0);
  const out = { hits, score, positives: hits.filter((h) => h.w > 0).length, negatives: hits.filter((h) => h.w < 0).length };
  _patCache.set(key, out);
  return out;
}
function PatternStrip({ c }) {
  const p = detectPatterns(c);
  const fam = getInstrumentTheme(c);
  const [open, setOpen] = useState(false);
  if (!p.hits.length) return null;
  return (
    <div data-stock data-nodrag style={{ padding: "8px 14px 0", background: fam.stock }}>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 5, alignItems: "center" }}>
        <span style={{ fontFamily: F.label, fontSize: 9, letterSpacing: 2, color: C.inkSoft, marginRight: 2 }}>PATTERNS</span>
        {p.hits.map((h) => (
          <button key={h.id} onClick={() => setOpen(open === h.id ? false : h.id)} style={{
            background: "transparent", cursor: "pointer", fontFamily: F.stat, fontSize: 10, padding: "2px 7px",
            border: `1px solid ${h.w < 0 ? hexA(C.red, .7) : hexA(fam.foil, .55)}`, color: h.w < 0 ? "#E08A7C" : fam.foilLt,
          }}>{h.icon} {h.label}</button>
        ))}
      </div>
      {open && (() => { const h = p.hits.find((x) => x.id === open); return (
        <div style={{ marginTop: 7, border: `1px solid ${C.edge}`, padding: "7px 9px" }}>
          <div style={{ fontFamily: F.body, fontSize: 12.5, color: C.ink, lineHeight: 1.45 }}>{h.why}</div>
          <div style={{ fontFamily: F.stat, fontSize: 10.5, color: C.inkSoft, marginTop: 4 }}>Evidence: {h.evidence}</div>
          <div style={{ fontFamily: F.stat, fontSize: 9.5, color: C.inkSoft, marginTop: 4 }}>A pattern is an observed combination on file, not a recommendation.</div>
        </div>); })()}
    </div>
  );
}



/* ============================== AMBIENCE DIRECTOR ==============================
 * Random idle acts drawn from the motion toolbelt, played one at a time with gaps,
 * never repeating the last one. Cards never change; acts happen around, behind
 * or briefly to the current card. The attention gate hushes everything the moment
 * the user reaches for something: pointer down, typing, any panel open, a
 * decision pending, list mode, or reduced motion.
 * ============================================================================ */
const ACTS = [
  { id: "sweep",     dur: 2600, w: 3 },   // 26 hover / gloss: a light pass across the table
  { id: "dust",      dur: 6000, w: 3 },   // 6 ambient background motion: gold dust rising
  { id: "contours",  dur: 5200, w: 3 },   // 8 self-drawing: topographic lines draw across the desk
  { id: "seal",      dur: 3800, w: 2 },   // 8 self-drawing icon: the instrument seal draws itself
  { id: "type",      dur: 3600, w: 2 },   // 4 expressive typography: the mantra floats in
  { id: "gradient",  dur: 5000, w: 2 },   // 18 animated gradient: a slow wash on the stone
  { id: "deal",      dur: 2400, w: 2 },   // 14 faux 3D: the card flips to its back and returns
  { id: "shuffle",   dur: 2200, w: 2 },   // 14 faux 3D: three ghost cards fan out and tuck in
  { id: "twinkle",   dur: 1800, w: 2 },   // 12 microinteraction: level gems light in sequence
  { id: "flipbook",  dur: 3200, w: 1 },   // 31 stop-motion: the corner badge flips through landscapes
  { id: "ripple",    dur: 2200, w: 2 },   // 17 liquid motion: a ring ripples out from the card
  { id: "morph",     dur: 5200, w: 2 },   // 9 morphing: a foil blob changes shape behind the table
  { id: "iso",       dur: 3600, w: 2 },   // 19 isometric: a parcel grid rises from the desk edge
  { id: "logo",      dur: 3200, w: 2 },   // 10 animated logo: the H coin spins, the wordmark underlines itself
  { id: "glass",     dur: 3000, w: 1 },   // 28 glassmorphic: a glass pane slides across
  { id: "doodle",    dur: 3400, w: 2 },   // 21 doodle: a hand-sketched house scribbles itself
  { id: "scout",     dur: 4800, w: 2 },   // 13 character: the Scout walks the bottom edge with a lens
  { id: "drift",     dur: 6000, w: 2 },   // 2/15 parallax: the camera drifts across the desk
  { id: "stamp",     dur: 1600, w: 1 },   // 31 stop-motion: a three-frame stamp slam in the corner
];
/** Routines: 1–3 acts chained with short beats between, like a dealer's flourish. */
const ROUTINES = [
  ["contours", "seal"], ["dust", "type"], ["shuffle", "deal"], ["drift", "sweep"], ["doodle", "stamp"], ["iso", "ripple"],
  ["logo"], ["morph", "glass"], ["scout"], ["twinkle", "sweep"], ["flipbook"], ["gradient", "dust"],
];
const pickRoutine = (last) => {
  const pool = ROUTINES.filter((r) => r.join() !== last);
  return pool[Math.floor(Math.random() * pool.length)];
};
const pickAct = (last) => {
  const pool = ACTS.filter((a) => a.id !== last);
  const total = pool.reduce((n, a) => n + a.w, 0);
  let r = Math.random() * total;
  for (const a of pool) { r -= a.w; if (r <= 0) return a; }
  return pool[0];
};

const MOTION_LEVELS = { off: null, calm: { first: 1500, gap: [7000, 14000] }, lively: { first: 700, gap: [2200, 5500] } };
function useAmbience(hushed, level) {
  const [act, setAct] = useState(null);
  const last = useRef(null);
  const timer = useRef(null);
  const hushRef = useRef(hushed);
  hushRef.current = hushed;
  const playRoutine = useRef(null);
  useEffect(() => {
    const cfg = MOTION_LEVELS[level];
    if (!cfg) { setAct(null); if (timer.current) clearTimeout(timer.current); timer.current = null; return; }
    let alive = true;
    const play = (ids, i, done) => {
      const a = ACTS.find((x) => x.id === ids[i]) || pickAct(null);
      setAct({ ...a, key: Date.now() });
      timer.current = setTimeout(() => {
        if (!alive) return;
        setAct(null);
        if (i + 1 < ids.length) timer.current = setTimeout(() => alive && play(ids, i + 1, done), 450 + Math.random() * 500);
        else done();
      }, a.dur);
    };
    const schedule = (gap) => {
      timer.current = setTimeout(() => {
        if (!alive) return;
        if (hushRef.current) return schedule(900);          // wait for the user to let go, keep the clock running
        const r = pickRoutine(last.current); last.current = r.join();
        play(r, 0, () => schedule(cfg.gap[0] + Math.random() * (cfg.gap[1] - cfg.gap[0])));
      }, gap);
    };
    playRoutine.current = () => { if (timer.current) clearTimeout(timer.current); const r = pickRoutine(last.current); last.current = r.join();
      play(r, 0, () => schedule(cfg.gap[0] + Math.random() * (cfg.gap[1] - cfg.gap[0]))); };
    schedule(cfg.first);
    return () => { alive = false; if (timer.current) clearTimeout(timer.current); };
  }, [level]);
  return [act, () => playRoutine.current && playRoutine.current()];
}

/** Attention gate: true while the user is doing something that motion would get in the way of. */
function useAttention(extraBusy) {
  const [busy, setBusy] = useState(false);
  const holding = useRef(false);
  const typingUntil = useRef(0);
  useEffect(() => {
    const isTyping = () => document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName);
    const recompute = () => setBusy(holding.current || isTyping() || Date.now() < typingUntil.current);
    const down = () => { holding.current = true; recompute(); };
    const up = () => { holding.current = false; setTimeout(recompute, 350); };
    const key = () => { typingUntil.current = Date.now() + 1200; recompute(); };
    const iv = setInterval(recompute, 400);
    window.addEventListener("pointerdown", down, { passive: true });
    window.addEventListener("pointerup", up, { passive: true });
    window.addEventListener("pointercancel", up, { passive: true });
    window.addEventListener("keydown", key, { passive: true });
    window.addEventListener("focusin", recompute);
    window.addEventListener("focusout", recompute);
    return () => { clearInterval(iv); window.removeEventListener("pointerdown", down); window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up); window.removeEventListener("keydown", key);
      window.removeEventListener("focusin", recompute); window.removeEventListener("focusout", recompute); };
  }, []);
  return busy || !!extraBusy;
}

/* --------------------------------- card back ---------------------------------- */
function CardBack() {
  return (
    <div style={{ position: "absolute", inset: 0, borderRadius: 18, overflow: "hidden", backfaceVisibility: "hidden", transform: "rotateY(180deg)",
      backgroundImage: `${BRUSH}, ${METAL.charcoal}`, boxShadow: "inset 0 1px 0 rgba(255,255,255,.2), 0 30px 56px rgba(0,0,0,.7)" }}>
      <div style={{ position: "absolute", inset: 9, borderRadius: 10, border: `1px solid ${hexA(C.gold, .5)}`, background: "#101215",
        backgroundImage: "repeating-radial-gradient(circle at 50% 50%, rgba(201,164,76,.14) 0 1px, transparent 1px 9px), repeating-linear-gradient(45deg, rgba(255,255,255,.03) 0 1px, transparent 1px 8px)" }}>
        <div style={{ position: "absolute", inset: 18, border: `1px solid ${hexA(C.gold, .3)}`, borderRadius: 6 }} />
        <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 8 }}>
          <div style={{ width: 84, height: 84, borderRadius: "50%", backgroundImage: `${BRUSH}, radial-gradient(circle at 35% 30%, #F6E7B4, #C9A44C 55%, #7A5A16)`,
            boxShadow: "inset 0 2px 0 rgba(255,255,255,.5), inset 0 -4px 8px rgba(0,0,0,.5), 0 6px 14px rgba(0,0,0,.7)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ fontFamily: F.name, fontSize: 40, fontWeight: 700, color: "#2B2007", textShadow: "0 1px 0 rgba(255,255,255,.4)" }}>H</span>
          </div>
          <div style={{ fontFamily: F.label, fontSize: 10, letterSpacing: 3.4, color: C.goldLt, textShadow: EMBOSS }}>HANDS ON TAX LIENS</div>
          <div style={{ fontFamily: F.stat, fontSize: 8.5, letterSpacing: 2, color: C.inkSoft }}>COUNTYDEX · SCOUTING DEPARTMENT</div>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------ ambient layers -------------------------------- */
function Ambience({ act, fam }) {
  if (!act) return null;
  const foil = fam ? fam.foilLt : C.goldLt;
  const layer = { position: "fixed", inset: 0, pointerEvents: "none", zIndex: 2 };
  if (act.id === "sweep") return <div key={act.key} className="amb ambSweep" style={{ ...layer, zIndex: 30, mixBlendMode: "screen",
    background: "linear-gradient(105deg, transparent 40%, rgba(255,255,255,.34) 50%, transparent 60%)", backgroundSize: "260% 100%", opacity: "var(--amb)" }} />;
  if (act.id === "gradient") return <div key={act.key} className="amb ambWash" style={{ ...layer, opacity: 0, mixBlendMode: "screen",
    background: `radial-gradient(60% 40% at 30% 20%, ${hexA(foil, .36)}, transparent 70%), radial-gradient(50% 40% at 75% 70%, rgba(78,208,224,.26), transparent 70%)`, backgroundSize: "200% 200%" }} />;
  if (act.id === "dust") return (
    <div key={act.key} style={layer}>
      {Array.from({ length: 22 }).map((_, i) => (
        <span key={i} className="amb ambDust" style={{ position: "absolute", left: `${(i * 37) % 100}%`, bottom: -8, width: 2 + (i % 3), height: 2 + (i % 3), borderRadius: "50%",
          background: foil, boxShadow: `0 0 8px ${hexA(foil, 1)}, 0 0 16px ${hexA(foil, .6)}`, animationDelay: `${(i % 7) * .35}s`, animationDuration: `${4 + (i % 5) * .6}s`, opacity: 0 }} />
      ))}
    </div>);
  if (act.id === "contours") return (
    <svg key={act.key} className="amb" viewBox="0 0 1200 800" preserveAspectRatio="none" style={{ ...layer, width: "100%", height: "100%", opacity: .8 }}>
      {[0, 1, 2, 3, 4].map((i) => (
        <path key={i} className="ambDraw" style={{ animationDelay: `${i * .35}s` }} fill="none" stroke={foil} strokeWidth="1.6"
          d={`M-20 ${140 + i * 130} C 200 ${90 + i * 130}, 380 ${230 + i * 130}, 600 ${150 + i * 130} S 1000 ${60 + i * 130}, 1240 ${180 + i * 130}`} />
      ))}
    </svg>);
  if (act.id === "seal") return (
    <svg key={act.key} className="amb ambFade" viewBox="0 0 48 48" width="120" height="120" fill="none" stroke={foil} strokeWidth="1.2"
      style={{ position: "fixed", right: 24, bottom: 24, pointerEvents: "none", zIndex: 2, opacity: .9 }}>
      {fam && fam.key === "deed"
        ? [<path key="a" className="ambDraw" d="M4 20 L24 5 L44 20" />, <path key="b" className="ambDraw" style={{ animationDelay: ".4s" }} d="M9 18v22h30V18" />,
           <path key="c" className="ambDraw" style={{ animationDelay: ".8s" }} d="M14 40V27h9v13" />, <circle key="d" className="ambDraw" style={{ animationDelay: "1.2s" }} cx="35" cy="37" r="4.2" />]
        : [<circle key="a" className="ambDraw" cx="24" cy="24" r="21" />, <path key="b" className="ambDraw" style={{ animationDelay: ".4s" }} d="M15 14h13l5 5v15H15z" />,
           <path key="c" className="ambDraw" style={{ animationDelay: ".8s" }} d="M19 33l10-10" />, <path key="d" className="ambDraw" style={{ animationDelay: "1.2s" }} d="M24 3a21 21 0 0 1 21 21" strokeWidth="2.2" />]}
    </svg>);
  if (act.id === "type") {
    const words = ["SCOUT", "VERIFY", "CAPTURE", "DECIDE", "RECORD"];
    return (
      <div key={act.key} className="amb" style={{ ...layer, display: "flex", alignItems: "flex-end", justifyContent: "center", paddingBottom: 26 }}>
        <div style={{ display: "flex", gap: 14 }}>
          {words.map((w, i) => <span key={w} className="ambWord" style={{ fontFamily: F.label, fontSize: 15, letterSpacing: 5, color: foil, textShadow: `0 0 10px ${hexA(foil, .7)}, 0 1px 0 rgba(0,0,0,.8)`, animationDelay: `${i * .22}s`, opacity: 0 }}>{w}</span>)}
        </div>
      </div>);
  }
  if (act.id === "morph") return <div key={act.key} className="amb ambMorph" style={{ position: "fixed", left: "8%", top: "18%", width: 220, height: 220, pointerEvents: "none", zIndex: 1, opacity: 0,
    background: `radial-gradient(circle at 35% 30%, ${hexA(foil, .55)}, ${hexA(foil, .12)} 60%, transparent 75%)`, filter: "blur(1px)" }} />;
  if (act.id === "iso") return (
    <div key={act.key} style={{ ...layer, display: "flex", alignItems: "flex-end", justifyContent: "center", paddingBottom: 18 }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(6, 22px)", gap: 3, transform: "rotateX(58deg) rotateZ(45deg)", transformStyle: "preserve-3d", opacity: 1 }}>
        {Array.from({ length: 36 }).map((_, i) => (
          <span key={i} className="amb ambIso" style={{ display: "block", width: 22, height: 22, border: `1px solid ${hexA(foil, .95)}`, background: hexA(foil, .22), boxShadow: `0 0 8px ${hexA(foil, .4)}`, animationDelay: `${(i % 6) * .08 + Math.floor(i / 6) * .08}s`, opacity: 0 }} />
        ))}
      </div>
    </div>);
  if (act.id === "glass") return <div key={act.key} className="amb ambGlass" style={{ position: "fixed", top: 0, bottom: 0, left: "-40%", width: "34%", pointerEvents: "none", zIndex: 30, transform: "skewX(-12deg)",
    background: "linear-gradient(90deg, rgba(255,255,255,.04), rgba(255,255,255,.18) 50%, rgba(255,255,255,.04))", backdropFilter: "blur(4px)", WebkitBackdropFilter: "blur(4px)", borderLeft: "1px solid rgba(255,255,255,.35)", borderRight: "1px solid rgba(255,255,255,.35)" }} />;
  if (act.id === "doodle") return (
    <svg key={act.key} className="amb ambFade" viewBox="0 0 120 100" width="150" height="125" fill="none" stroke={foil} strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"
      style={{ position: "fixed", left: 20, bottom: 30, pointerEvents: "none", zIndex: 2, opacity: .85 }}>
      <path className="ambDraw" d="M12 60 Q35 22 60 40 Q80 25 104 58" />
      <path className="ambDraw" style={{ animationDelay: ".5s" }} d="M22 58 L23 90 Q60 96 96 89 L95 57" />
      <path className="ambDraw" style={{ animationDelay: "1s" }} d="M48 90 L48 70 Q58 66 68 70 L68 89" />
      <path className="ambDraw" style={{ animationDelay: "1.4s" }} d="M76 48 L76 34 L84 34 L84 55" />
      <path className="ambDraw" style={{ animationDelay: "1.8s" }} d="M30 72 h10 M78 72 h10" />
      <path className="ambDraw" style={{ animationDelay: "2.1s" }} d="M104 62 Q112 60 116 64 M12 64 Q6 62 4 66" strokeDasharray="2 3" />
    </svg>);
  if (act.id === "scout") return (
    <div key={act.key} className="amb ambWalk" style={{ position: "fixed", bottom: 14, left: -80, pointerEvents: "none", zIndex: 2 }}>
      <svg viewBox="0 0 60 70" width="64" height="76" fill="none" stroke={foil} strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{ filter: `drop-shadow(0 0 6px ${hexA(foil, .7)})` }}>
        <circle cx="30" cy="14" r="7" /><path d="M20 12 h20 M23 8 h14" />
        <path d="M30 21 v22" /><path className="scoutArm" d="M30 28 L18 36" /><path d="M30 28 L42 34 L50 30" />
        <circle cx="53" cy="28" r="5" strokeWidth="1.4" /><path d="M57 32 l5 5" strokeWidth="1.4" />
        <path className="scoutLegA" d="M30 43 L22 62" /><path className="scoutLegB" d="M30 43 L38 62" />
      </svg>
    </div>);
  if (act.id === "drift") return <div key={act.key} className="amb ambDrift" style={{ ...layer, zIndex: 0, opacity: .5, mixBlendMode: "soft-light",
    backgroundImage: `url("data:image/svg+xml,${encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="240" height="240"><filter id="s"><feTurbulence type="fractalNoise" baseFrequency="0.01" numOctaves="3"/></filter><rect width="240" height="240" filter="url(#s)"/></svg>')}")`, backgroundSize: "480px 480px" }} />;
  if (act.id === "stamp") return (
    <div key={act.key} className="amb ambStamp" style={{ position: "fixed", right: 28, top: 88, pointerEvents: "none", zIndex: 30, transform: "rotate(-14deg)",
      fontFamily: F.label, fontSize: 13, letterSpacing: 3, color: hexA(foil, .9), padding: "6px 12px", border: `2px solid ${hexA(foil, .8)}`, borderRadius: 4,
      textShadow: EMBOSS, boxShadow: "0 6px 14px rgba(0,0,0,.6)", opacity: 0 }}>{fam && fam.key === "deed" ? "DEED" : "LIEN"} · SCOUTED</div>);
  if (act.id === "ripple") return (
    <div key={act.key} style={{ ...layer, display: "flex", alignItems: "center", justifyContent: "center" }}>
      {[0, 1, 2].map((i) => <span key={i} className="amb ambRing" style={{ position: "absolute", width: 260, height: 360, borderRadius: 24, border: `2px solid ${hexA(foil, .85)}`, boxShadow: `0 0 18px ${hexA(foil, .5)}`, animationDelay: `${i * .35}s`, opacity: 0 }} />)}
    </div>);
  return null;
}




/* ================================== THE HAND ==================================
 * Two or three cards held side by side, with a comparison beneath. Best-in-row
 * is highlighted on measurable things; the table never says which to buy — it
 * ends in "best fit for", read off the patterns, the way a scout would.
 * ============================================================================ */
const HandCtx = React.createContext({ hand: [], toggleHand: () => {} });
const ShareCtx = React.createContext(null);
function HandButton({ c, small }) {
  const { hand, toggleHand } = useContext(HandCtx);
  const on = hand.includes(c.id);
  const full = hand.length >= 3 && !on;
  return (
    <button data-nodrag onClick={(e) => { e.stopPropagation(); if (!full) toggleHand(c.id); }} title={full ? "Hand is full — drop one first" : on ? "Remove from hand" : "Hold in hand to compare"}
      style={{ ...chip, padding: small ? "1px 6px" : "3px 9px", fontSize: small ? 9.5 : 10.5, cursor: full ? "not-allowed" : "pointer",
        borderColor: on ? C.goldLt : full ? C.line : hexA(C.gold, .55), color: on ? C.goldLt : full ? C.dim : C.goldLt, opacity: full ? .5 : 1 }}>
      {on ? "✓ In hand" : "+ Hand"}
    </button>
  );
}

const FIT_TAGS = [
  ["Yield hunter", (r) => r.fixed || (r.rate != null && r.rate >= 15)],
  ["Low competition", (r) => r.thin || (r.floorShare != null && r.floorShare < 20) || (r.bidders != null && r.bidders < 100)],
  ["Fast turnover", (r) => r.fast],
  ["Deed hunter", (r) => r.acquire],
  ["OTC investor", (r) => r.otc === "link"],
  ["Data-driven", (r) => r.edge || !!r.results],
  ["Beginner", (r) => r.verifiedState && r.facts >= 5 && /online|realauction|lienhub|govease|sri|zeus/i.test(r.platform || "")],
  ["Small investor", (r) => r.face != null && r.face <= 1200],
  ["Home turf", (r) => r.home],
];

function compareRow(c, checks) {
  const R = rulesFor(c.state), cap = captureOf(c, checks), p = detectPatterns(c), stats = OUTCOME_STATS[`${c.state}|${c.name}`];
  const row = NAT_BY_NAME[`${c.name}|${c.state}`];
  const ns = NEXT_SALE[`${c.state}|${c.name}`];
  const has = (id) => p.hits.some((h) => h.id === id);
  const platform = (c.facts || []).find((f) => /platform/i.test(f[0]))?.[1] || (c.stats && c.stats["Auction frequency"]) || null;
  return {
    c, id: c.id, name: `${c.name}, ${c.state}`, instrument: getInstrumentTheme(c).label,
    rate: R.statutoryRate, mechanism: R.verified ? R.headline : (row ? row[5] + " (unverified)" : "unknown"),
    win: stats ? (stats.weighted_rate ?? stats.avg_rate) : null, redemption: R.redemption || (row && row[6] ? `${row[6]} months` : "unknown"),
    redeemMo: row ? row[6] : null, nextSale: ns || null, saleDays: ns ? Math.round((new Date(ns) - TODAY) / 86400000) : null,
    saleThrough: stats ? stats.sale_through_pct : null, bidders: stats ? stats.bidders : null, floorShare: stats ? stats.floor_share_pct : null,
    deedPct: stats ? stats.deed_to_sold_pct : null, results: stats ? stats.latest_year : null,
    otc: row && row[18] ? "link" : COUNTY_VERIFIED.otc_state[c.state] ? "state" : null,
    facts: (c.facts || []).filter((f) => f[2] === "g").length, research: cap.pct, missing: cap.missing.length,
    priority: row ? row[7] : (c.scores ? c.scores.opportunity : null), patternScore: p.score, patterns: p.hits.map((h) => h.icon + " " + h.label).join("  "),
    verifiedState: R.verified, face: c.yieldModel?.defaultFace ?? null, platform,
    fixed: has("fixed"), thin: has("thin"), fast: has("fast"), acquire: has("acquire"), edge: has("edge"), home: has("home"),
    opp: c.scores ? c.scores.opportunity : null, conf: c.scores ? c.scores.confidence : null,
  };
}



/* ============================== THE DEALER ====================================
 * One continuous 20-second routine, every card a random county from the whole
 * deck with a real face on the other side:
 *   riffle → bridge → waterfall → ribbon spread → wave turnover (faces flip up)
 *   → gather → triple cut → boomerang → square up → rest on your card
 * Hover the spread to freeze it and read the faces. Click any face to jump the
 * deck to that county. Touch anywhere else and it snaps back to your card.
 * ============================================================================ */
const SLIVERS = 26;


/* ================================ DECK PLAY ===================================
 * When the table is idle the deck plays with itself: it peeks at other counties,
 * fans the next few, flips to a rival, deals a hand, and nudges you toward the
 * research you have not done. Every play is built from real cards and real
 * hooks — items left, sale windows, results on file — because the point is to
 * make someone want to open the board. Touch anything and it snaps back to the
 * card you were on, untouched.
 * ============================================================================ */
const PLAYS = [
  { id: "peek",   dur: 4200 },   // another card rises over yours, shows its hook, slides away
  { id: "fan",    dur: 3600 },   // the next three fan out behind, then tuck
  { id: "flip",   dur: 4600 },   // flips to the back, comes back as a rival, then returns
  { id: "deal",   dur: 4400 },   // deals a three-card hand across the table, gathers it
  { id: "nudge",  dur: 3200 },   // your card leans in; the capture meter shows what is left
  { id: "coin",   dur: 2600 },   // a coin flips; lands on one of your card's patterns
];

/** The most tempting true thing about a county, for a teaser ribbon. */
function hookFor(c, checks) {
  const cap = captureOf(c, checks);
  const p = detectPatterns(c);
  const ns = NEXT_SALE[`${c.state}|${c.name}`];
  const days = ns ? Math.round((new Date(ns) - TODAY) / 86400000) : null;
  if (cap.captured) return { t: `Captured · ${CARD_STATE[cap.tier].label}`, tone: "g" };
  if (cap.missing.length <= 3) return { t: `${cap.missing.length} required item${cap.missing.length === 1 ? "" : "s"} from capture · +${cap.missing.length * 25 + CAPTURE_XP} XP`, tone: "g" };
  if (days != null && days >= 0 && days <= 90) return { t: `Sale in ${days} days · ${cap.missing.length} items to clear first`, tone: "y" };
  if (OUTCOME_STATS[`${c.state}|${c.name}`]) return { t: `County-published results on file`, tone: "g" };
  const top = p.hits.find((h) => h.w > 0);
  if (top) return { t: `${top.icon} ${top.label} · ${cap.missing.length} items to capture`, tone: "y" };
  if (cap.tier === "undiscovered") return { t: `Never opened · first ${25} XP is one link away`, tone: "r" };
  return { t: `${cap.pct}% researched · ${cap.missing.length} required items left`, tone: "y" };
}


function useDeckPlay(enabled, idleMs, candidates, current, style) {
  const [play, setPlay] = useState(null);
  const lastTouch = useRef(Date.now());
  const timer = useRef(null);
  const lastId = useRef(null);
  const others = useRef([]);
  others.current = candidates;
  const rearm = useRef(null);
  useEffect(() => {
    const touch = () => { lastTouch.current = Date.now(); if (timer.current) clearTimeout(timer.current); timer.current = null;
      setPlay((p) => (p ? { ...p, ending: true, key: p.key } : null)); setTimeout(() => { setPlay(null); rearm.current && rearm.current(); }, 260); };
    window.addEventListener("pointerdown", touch, { passive: true });
    window.addEventListener("keydown", touch, { passive: true });
    window.addEventListener("wheel", touch, { passive: true });
    return () => { window.removeEventListener("pointerdown", touch); window.removeEventListener("keydown", touch); window.removeEventListener("wheel", touch); };
  }, []);
  useEffect(() => {
    if (!enabled) { setPlay(null); if (timer.current) clearTimeout(timer.current); timer.current = null; return; }
    let alive = true;
    const loop = () => {
      timer.current = setTimeout(() => {
        timer.current = null;
        if (!alive) return;
        if (Date.now() - lastTouch.current < idleMs) return loop();
        if (style === "dealer") {
          // half from your queue, half from anywhere in the country, fresh every time the routine starts
          const cur = current && current.id;
          const anywhere = Array.from({ length: 16 }, () => nationalCounty(NATIONAL[Math.floor(Math.random() * NATIONAL.length)])).filter((c) => c.id !== cur);
          const seen = new Set();
          const arr = [...[...others.current].sort(() => Math.random() - .5).slice(0, 14), ...anywhere].filter((c) => (seen.has(c.id) ? false : (seen.add(c.id), true))).sort(() => Math.random() - .5).slice(0, 26);
          setPlay({ id: "dealer", key: Date.now(), cards: arr });
          return;   // the routine loops in CSS until a touch ends it; the touch handler restarts the loop
        }
        const pool = PLAYS.filter((p) => p.id !== lastId.current && (others.current.length >= 3 || !["fan", "deal"].includes(p.id)) && (others.current.length >= 1 || !["peek", "flip"].includes(p.id)));
        const p = pool[Math.floor(Math.random() * pool.length)];
        lastId.current = p.id;
        const pick = (n) => { const arr = [...others.current].sort(() => Math.random() - .5); return arr.slice(0, n); };
        setPlay({ ...p, key: Date.now(), cards: pick(3) });
        timer.current = setTimeout(() => { if (alive) { setPlay(null); loop(); } }, p.dur);
      }, 1800 + Math.random() * 2600);
    };
    rearm.current = () => { if (alive && !timer.current) loop(); };
    loop();
    return () => { alive = false; rearm.current = null; if (timer.current) clearTimeout(timer.current); };
  }, [enabled, idleMs, style]);
  return play;
}

function CardBackFace() {
  return (
    <div style={{ position: "absolute", inset: 0, borderRadius: 18, overflow: "hidden", backgroundImage: `${BRUSH}, ${METAL.charcoal}`, boxShadow: "inset 0 1px 0 rgba(255,255,255,.2)" }}>
      <div style={{ position: "absolute", inset: 9, borderRadius: 10, border: `1px solid ${hexA(C.gold, .5)}`, background: "#101215",
        backgroundImage: "repeating-radial-gradient(circle at 50% 50%, rgba(201,164,76,.14) 0 1px, transparent 1px 9px)", display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 8 }}>
        <div style={{ width: 70, height: 70, borderRadius: "50%", backgroundImage: `${BRUSH}, radial-gradient(circle at 35% 30%, #F6E7B4, #C9A44C 55%, #7A5A16)`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F.name, fontSize: 34, fontWeight: 700, color: "#2B2007" }}>H</div>
        <div style={{ fontFamily: F.label, fontSize: 9, letterSpacing: 3, color: C.goldLt }}>HANDS ON TAX LIENS</div>
      </div>
    </div>
  );
}




/* ================================ SCOUT LOADOUT ================================
 * The loadout is who you are as a scout: a class, a capital band, a horizon, how
 * much competition you will tolerate, whether you travel, whether you hunt bosses,
 * and where home is. It drives fit scores, mission suggestions, deck ordering and
 * the calculator's defaults. It never changes a fact, a tier, or a clearance.
 * ============================================================================ */
const CLASSES = {
  yield:       { name: "Yield Scout",       icon: "%", line: "Interest first. Redemption is the exit.",           base: { yield: 5, acquisition: 1, speed: 4, risk: 2, reach: 3 }, strategy: "yield" },
  acquisition: { name: "Acquisition Scout", icon: "⌂", line: "Wants the dirt. Deeds and redeemable deeds.",         base: { yield: 2, acquisition: 5, speed: 1, risk: 4, reach: 3 }, strategy: "acquisition" },
  land:        { name: "Land Scout",        icon: "▲", line: "Vacant land, access, easements, wells and septic.",   base: { yield: 2, acquisition: 4, speed: 2, risk: 3, reach: 4 }, strategy: "land" },
  metro:       { name: "Metro Scout",       icon: "▦", line: "Residential markets, infill, online sales.",         base: { yield: 3, acquisition: 3, speed: 4, risk: 2, reach: 2 }, strategy: "metro" },
  value:       { name: "Deep Value Scout",  icon: "◆", line: "Low lien-to-value, thin lists, rural courthouses.",   base: { yield: 3, acquisition: 4, speed: 2, risk: 4, reach: 5 }, strategy: "value" },
};
/** Picking a class sets the dials to that class's defaults; every dial stays adjustable. */
const CLASS_PRESET = {
  yield:       { holdMonths: 18, competition: .5, deedAppetite: .2, travel: false, boss: false, otcFocus: false, capitalBand: 5000 },
  acquisition: { holdMonths: 30, competition: .5, deedAppetite: .9, travel: true,  boss: false, otcFocus: false, capitalBand: 8000 },
  land:        { holdMonths: 36, competition: .3, deedAppetite: .8, travel: true,  boss: true,  otcFocus: true,  capitalBand: 4000 },
  metro:       { holdMonths: 12, competition: .7, deedAppetite: .4, travel: false, boss: false, otcFocus: false, capitalBand: 10000 },
  value:       { holdMonths: 36, competition: .2, deedAppetite: .7, travel: true,  boss: true,  otcFocus: true,  capitalBand: 2500 },
};
const DEFAULT_LOADOUT = { cls: "yield", ...CLASS_PRESET.yield, homeStates: ["CO", "ID", "WA"], reach: 2 };
const LoadoutCtx = React.createContext({ loadout: DEFAULT_LOADOUT, setLoadout: () => {} });

/** How well a county fits this scout — with the reasons, so the number can be argued with. */
function loadoutFit(c, lo, checks) {
  const R = rulesFor(c.state), p = detectPatterns(c), fam = getInstrumentTheme(c), dif = difficultyOf(c);
  const has = (id) => p.hits.some((h) => h.id === id);
  const stats = OUTCOME_STATS[`${c.state}|${c.name}`];
  const blob = (c.facts || []).map((f) => f[0] + " " + f[1]).join(" ").toLowerCase();
  const inPerson = /in person|oral auction|certified funds|same-day/.test(blob);
  const online = /online|realauction|lienhub|govease|sri |zeus|bid4assets|iowataxauction/.test(blob);
  const m = [], x = [];
  let score = 50;
  // instrument vs appetite
  if (fam.key === "deed") { if (lo.deedAppetite >= .6) { score += 18; m.push("deed instrument fits your appetite"); } else if (lo.deedAppetite <= .3) { score -= 18; x.push("deed state, low deed appetite"); } }
  else { if (lo.deedAppetite <= .4) { score += 10; m.push("lien certificate, income-first"); } else if (lo.deedAppetite >= .8) { score -= 8; x.push("lien state, you want dirt"); } }
  // horizon
  const redeem = R.verified && R.redemption ? (parseInt((R.redemption.match(/(\d+)\s*year/) || [])[1] || "0", 10) * 12 || parseInt((R.redemption.match(/(\d+)\s*mo/) || [])[1] || "0", 10)) : null;
  if (redeem) { if (redeem <= lo.holdMonths) { score += 10; m.push(`redemption ${redeem} mo inside your ${lo.holdMonths} mo horizon`); } else { score -= 10; x.push(`redemption ${redeem} mo beyond your ${lo.holdMonths} mo horizon`); } }
  if (has("fast")) { score += 6; m.push("fast reload"); }
  if (has("income") && lo.deedAppetite >= .6) { score -= 14; x.push("deeds rare here by the county's own numbers"); }
  if (has("acquire") && lo.deedAppetite >= .6 && lo.homeStates.includes(c.state)) { score += 6; m.push("deed state at home"); }
  // competition tolerance
  if (has("floor") || (stats && stats.floor_share_pct >= 40)) { if (lo.competition < .5) { score -= 16; x.push("floor crowded, low competition tolerance"); } else { score += 4; m.push("crowded but you can live with it"); } }
  if (has("fixed")) { score += 12; m.push("fixed-rate shield"); }
  if (has("thin")) { score += lo.competition < .5 ? 12 : 4; m.push("thin list, less bidding"); }
  if (R.mechanism === "premium" && lo.competition < .4) { score -= 6; x.push("premium bid state punishes tight bidders"); }
  // travel and sale format
  if (inPerson) { if (lo.travel) { score += 8; m.push("in-person sale, you travel"); } else { score -= 14; x.push("in-person sale, you do not travel"); } }
  if (online && !lo.travel) { score += 6; m.push("online sale"); }
  // boss counties
  if (dif >= 5) { if (lo.boss) { score += 8; m.push("boss county, you hunt them"); } else { score -= 12; x.push("boss county, bosses off"); } }
  // geography / reach
  if (lo.homeStates.includes(c.state)) { score += 10; m.push("home state"); }
  else if (lo.reach <= 1) { score -= 12; x.push("outside home states, reach set to home only"); }
  else if (lo.reach === 2 && !["MT", "UT", "OR", "NV", "WY", "AZ", "NM"].includes(c.state) && !lo.homeStates.includes(c.state)) { score -= 5; x.push("outside your region"); }
  // OTC
  if (lo.otcFocus) { if (has("otc")) { score += 12; m.push("OTC list on file"); } else { score -= 6; x.push("no OTC link yet"); } }
  // capital band vs typical face
  const face = c.yieldModel?.defaultFace ?? null;
  if (face != null) { if (face <= lo.capitalBand) { score += 4; m.push(`typical lien $${face.toLocaleString()} within your $${lo.capitalBand.toLocaleString()} band`); } else { score -= 8; x.push(`typical lien $${face.toLocaleString()} above your band`); } }
  // class flavor
  const cls = CLASSES[lo.cls];
  if (cls.strategy === "metro" && /metro|city/i.test(themeOf(c).character)) { score += 6; m.push("metro character"); }
  if (cls.strategy === "land" && /rural|farm|ranch|range|wetland|lake/i.test(themeOf(c).character)) { score += 6; m.push("land character"); }
  if (cls.strategy === "value" && (has("thin") || dif >= 4)) { score += 6; m.push("deep-value profile"); }
  if (!R.verified) { score -= 10; x.push("state rules unverified"); }
  return { score: Math.max(0, Math.min(100, Math.round(score))), matches: m, mismatches: x };
}

