/** HOTL Edge Score for a county: informational advantage established, never investment quality. */
function edgeScore(c, checks) {
  const cap = captureOf(c, checks);
  const r = NAT_BY_NAME[`${c.name}|${c.state}`];
  const kinds = r && r[22] ? Object.keys(r[22]).length : 0;
  const facts = (c.facts || []).filter((f) => f[2] === "g").length;
  const sourceCoverage = Math.min(100, kinds * 12 + facts * 8);
  const conf = getConfidenceTreatment(c).conf;
  const fresh = FRESHNESS(c.verifiedCounty ? SOURCE_DATES.countyPages : r && r[22] ? SOURCE_DATES.database : null);
  const freshness = fresh.label === "FRESH" ? 100 : fresh.label === "RECENT" ? 85 : fresh.label === "AGING" ? 55 : fresh.label === "STALE" ? 25 : 0;
  const ns = NEXT_SALE[`${c.state}|${c.name}`];
  const edgeDays = ns ? daysBetween(SOURCE_DATES.countyPages, ns) : null;
  const timeAdv = edgeDays == null ? 0 : Math.min(100, Math.max(0, edgeDays) * 2);
  const agreement = c.conflict ? 20 : rulesFor(c.state).stale ? 60 : 100;
  const uniq = Math.min(100, detectPatterns(c).positives * 25);
  const unknownRed = cap.pct;
  const parts = [["Source coverage", .20, sourceCoverage], ["Verification confidence", .20, conf], ["Data freshness", .15, freshness], ["Time advantage", .15, timeAdv],
    ["Cross-source agreement", .10, agreement], ["Signal uniqueness", .10, uniq], ["Unknown reduction", .10, unknownRed]];
  const score = Math.round(parts.reduce((a, [, w, v]) => a + w * v, 0));
  return { score, parts, edgeDays, fresh, label: score >= 85 ? "EXCEPTIONAL INTELLIGENCE ADVANTAGE" : score >= 70 ? "STRONG ADVANTAGE" : score >= 50 ? "PARTIAL ADVANTAGE" : score >= 30 ? "THIN" : "NO ADVANTAGE YET" };
}

/** Signals: real changes and states on file, with severity, confidence, evidence and a next step. */
function signalQueue(checks) {
  const ev = realEvents(checks);
  const q = { "ACT NOW": [], "RESEARCH NOW": [], "WATCH": [], "CHANGED": [], "NEW": [], "RISK DETECTED": [] };
  for (const e of ev) {
    const cap = captureOf(e.c, checks);
    const base = { county: e.c, title: e.title, body: e.body, evidence: e.c.sources && e.c.sources.length ? e.c.sources[0][0] : "county record", confidence: e.kind === "data" ? 99 : e.kind === "auction" ? 95 : 85 };
    if (e.kind === "auction") { const days = parseInt((e.body.match(/in (\d+) days/) || [])[1] || "999", 10);
      (days <= 45 ? q["ACT NOW"] : q["WATCH"]).push({ ...base, severity: days <= 45 ? "URGENT" : "WATCH", step: `${cap.missing.length} required checks before ${e.c.name}'s sale` }); }
    else if (e.kind === "rule") q["RISK DETECTED"].push({ ...base, severity: "IMPORTANT", step: "Resolve the conflict against the statute; do not carry the lower figure" });
    else if (e.kind === "stale") q["CHANGED"].push({ ...base, severity: "WATCH", step: "Re-open the county page and refresh the sale record" });
    else q["NEW"].push({ ...base, severity: "INFO", step: "Fold the published results into the yield calculator" });
  }
  const near = NATIONAL.map((r) => nationalCounty(r)).map((c) => ({ c, cap: captureOf(c, checks) })).filter((x) => !x.cap.captured && x.cap.missing.length <= 3).slice(0, 4);
  for (const x of near) q["RESEARCH NOW"].push({ county: x.c, title: `${x.cap.missing.length} CHECKS FROM CAPTURE`, body: x.cap.missing[0].text, evidence: "capture record", confidence: 100, severity: "INFO", step: x.cap.missing[0].text });
  return q;
}

