/* All 3,143 counties — one record per line, fields separated by |. The board no
   longer carries a subset: a county the platform is blind on is exactly the kind
   you want the map to show as dark, and trimming them hid the gap instead of
   naming it. */
const _NUM = new Set([2, 4, 6, 7, 10, 14, 15, 20]);
const NATIONAL = _NAT.split("\n").map((line) => {
  const c = line.split("|");
  const row = c.map((v, i) => (v === "" ? (_NUM.has(i) ? null : "") : _NUM.has(i) ? Number(v) : v));
  row[22] = c[22] ? Object.fromEntries(c[22].split(",").map((p) => {
    const i = p.indexOf(":"), k = p.slice(0, i), [u, lv] = p.slice(i + 1).split("~");
    return [k, [u === "" ? 0 : u, lv]];
  })) : {};
  return row;
});

