/** Turn a queue row into a lightweight county record the existing card stack understands. */
const _natCountyCache = new Map();
let _richByName = null;
function nationalCounty(row) {
  if (_natCountyCache.has(row[2])) return _natCountyCache.get(row[2]);
  const c = buildNationalCounty(row);
  _natCountyCache.set(row[2], c);
  return c;
}
function buildNationalCounty(row) {
  const [county, state, geoid, sys, rate, bid, redeem, score, tier, flags, verified, phone, email, site, nOfficial, outcome, headline, conflict, otcUrl, otcLevel, population, terrain, dbl, dbSite] = row;
  const id = `nat-${geoid}`;
  if (!_richByName) { _richByName = new Map(); for (const c of ALL_COUNTIES) _richByName.set(`${c.name}|${c.state}`, c); }
  const rich = _richByName.get(`${county}|${state}`);
  if (rich) return rich; // the 15 researched cards win over their national stub

  const deep = COUNTY_VERIFIED.counties[`${state}|${county}`];
  const dor = state === "FL" ? COUNTY_VERIFIED.fl_dor_2026.rows[county] : null;
  const otcS = COUNTY_VERIFIED.otc_state[state];
  const otcC = COUNTY_VERIFIED.otc_county[`${state}|${county}`];
  const otcFact = otcC
    ? ["OTC", `${otcC[2]} — link on file (${otcC[1]})`, otcC[1] === "OFFICIAL" ? "g" : "y"]
    : otcS ? ["OTC", `${otcS.name} (${state} mechanism, ${otcS.level.toLowerCase()}) — no county link on file`, otcS.level === "OFFICIAL" ? "y" : "r"]
           : ["OTC", "Unknown for this state", "r"];
  if (deep || dor) {
    const facts = deep
      ? [...deep.facts.map(([k, v, lvl]) => [k, v, lvl === "OFFICIAL" ? "g" : "y"]), ...(deep.facts.some((f) => f[0] === "OTC") ? [] : [otcFact])]
      : [["2026 sale", headline, "g"], ["Platform", dor.platform, "g"],
         ...(dor.contact ? [["Contact", `${dor.contact} — per Florida DOR 2026 roster`, "g"]] : []),
         ["Bid method", "Rate bid down from 18%, 5% statutory minimum on redemption", "g"],
         ["County record", "Sale roster row from the Florida Department of Revenue; county terms not yet opened", "y"]];
    facts.push(otcFact);
    const links = deep ? deep.links : [...(dor.url ? [["platform", `${county} County tax certificate sale`, dor.url, "OFFICIAL"]] : []), COUNTY_VERIFIED.fl_dor_2026.source];
    return {
      id, name: county, state, seat: "", instrument: sys === "L" ? "Tax lien" : sys === "D" ? "Tax deed" : "Unknown",
      sourced: true, national: true, verifiedCounty: true, tier, priority: score, geoid, population, terrain,
      phone: (deep && deep.phone) || (dor && dor.phone) || phone || null, email,
      links, facts,
      sources: links.map(([, label, , lvl]) => [label, lvl, COUNTY_VERIFIED.checked]),
      conflict: (deep && deep.conflict) || null, stale: null,
      outcomeSources: deep ? deep.outcome_sources : [],
      unknowns: { known: facts.length, unknown: deep ? 3 : 6, conflicting: deep && deep.conflict ? 1 : 0, stale: 0,
        missing: deep ? ["Parcel count for the current sale", "Historical winning rates", "Redemption outcomes by year"]
                      : ["County terms document", "Deposit and registration rules", "Parcel count", "Historical outcomes", "Assessor and GIS links", "Recorder link"] },
      yieldModel: { defaultFace: 900, defaultAnnualTax: 300, medianHold: Math.max(6, Math.min(24, Math.round((redeem || 24) / 2))),
        winRate: rate || 0, premiumPct: bid === "premium" ? 10 : 0, feesFixed: 25,
        note: deep ? "County mechanics verified; winning rates and hold times are still assumptions until results are on file."
                   : "Roster-level verification only. Open the county terms before treating any input here as fact." },
    };
  }
  const facts = [
    ["Sale system", sys === "L" ? "Tax lien certificate" : sys === "D" ? "Tax deed" : "Unknown", sys === "?" ? "r" : "g"],
    ...(population ? [["Population", population.toLocaleString(), "g"]] : []),
    ...(terrain ? [["Terrain", terrain.charAt(0).toUpperCase() + terrain.slice(1) + " — from the county database", "g"]] : []),
    ["Statutory rate", rate ? `${rate}%` : "None stated (deed) or unknown", rate ? "g" : "y"],
    ["Bid method", bid, bid === "unknown" ? "r" : "g"],
    ["Redemption", redeem ? `${redeem} months` : "Unknown", redeem ? "g" : "y"],
    ["State rulebook", verified ? "Verified against primary sources" : "Workbook value — researched, not verified", verified ? "g" : "y"],
    ["County record", dbl && Object.keys(dbl).length ? `${Object.keys(dbl).length} direct link${Object.keys(dbl).length === 1 ? "" : "s"} on file from the county database — not yet opened` : "No county-level facts on file.", dbl && Object.keys(dbl).length ? "y" : "r"],
    otcFact,
  ];
  if (phone) facts.push(["Phone", `${phone} — scraped Aug 6, 2026, not yet verified`, "y"]);
  if (email) facts.push(["Email", `${email} — scraped Aug 6, 2026, not yet verified`, "y"]);
  if (site) facts.push(["Website", `${site} — derived from the email domain, not verified`, "y"]);
  if (flags.includes("R")) facts.push(["Source row", "Scraper wrote contact data into rate columns — contacts above were recovered from it", "y"]);
  if (flags.includes("G")) facts.push(["Regime conflict", "Source row disagreed with its own state layer about lien vs deed; state layer used", "y"]);
  return {
    id, name: county, state, seat: "", instrument: sys === "L" ? "Tax lien" : sys === "D" ? "Tax deed" : "Unknown",
    sourced: true, national: true, tier, priority: score, geoid, phone, email,
    links: dbSite ? [["treasurer", `${county} County — website (county database)`, unpackUrl(dbSite), "DIRECT"]] : site ? [["treasurer", `${county} County — candidate site (derived from ${email.split("@")[1]})`, site, "UNVERIFIED"]] : [],
    population, terrain,
    facts, sources: [], conflict: flags.includes("G") ? "Lien-or-deed conflict between the county row and the state layer. State statute governs; county row set aside." : null,
    stale: null,
    unknowns: { known: verified ? 4 : 3, unknown: 6, conflicting: flags.includes("G") ? 1 : 0, stale: 0,
      missing: ["Next sale date", "Auction platform", "Registration and deposit", "Parcel list source", "County contacts", "Historical outcomes"] },
    yieldModel: { defaultFace: 900, defaultAnnualTax: 300, medianHold: Math.max(6, Math.min(24, Math.round((redeem || 24) / 2))),
      winRate: rate || 0, premiumPct: bid === "premium" ? 10 : 0, feesFixed: 25,
      note: "Statutory layer only. Every county-level input on this screen is an assumption until a county source is on file." },
  };
}

const NATIONAL_STATES = [...new Set(NATIONAL.map((r) => r[1]))].sort();

/** Best link for the card title: verified treasurer page first, then a derived candidate. */
function primarySite(c) {
  const usable = (l) => l && typeof l[2] === "string" && l[2].length > 4;
  const own = [...(COUNTY_LINKS[c.id] || []), ...(c.links || []), ...dbLinks(c)].filter(usable);
  const t = own.find((l) => l[0] === "treasurer" && l[3] === "OFFICIAL") || own.find((l) => l[0] === "treasurer") || own.find((l) => l[0] === "assessor");
  if (t) return { url: t[2], level: t[3] };
  // The county's own page, straight off the national row — a separate field from the
  // county-database links, and the one most counties actually have.
  const r = NAT_BY_NAME[`${c.name}|${c.state}`];
  const site = r && (r[13] || (r[23] ? unpackUrl(r[23]) : null));
  return site ? { url: site, level: r[10] ? "OFFICIAL" : "DIRECT" } : null;
}
const NAT_BY_NAME = {};
for (const r of NATIONAL) NAT_BY_NAME[`${r[0]}|${r[1]}`] = r;
/** Phone for any county: featured cards pull it from the national scrape by name. */
function phoneFor(c) {
  const f = fipsOf(c);
  // a number the team has corrected beats both the scrape and the quarantine
  const fixed = liveGet(f, "phone");
  if (fixed) return fixed.value;
  // withheld: shared with a same-named county in another state, or marked so live
  const ws = liveGet(f, "phone_status");
  if (ws && /withheld/i.test(ws.value)) return null;
  if (PHONE_QUARANTINE.has(`${c.name}|${c.state}`)) return null;
  if (c.phone) return c.phone;
  const r = NAT_BY_NAME[`${c.name}|${c.state}`];
  return r && r[11] ? r[11] : null;
}
